from datetime import date, datetime, timedelta
from unittest.mock import patch

import pytest

from dispatch.case import scheduled
from dispatch.case.enums import CaseStatus


class _FakeDate(date):
    today_value = date(2025, 8, 18)

    @classmethod
    def today(cls):
        return cls.today_value


@pytest.mark.parametrize(
    "day, expected",
    [
        (date(2025, 8, 18), True),  # Monday
        (date(2025, 8, 19), False),
        (date(2025, 8, 24), False),  # Sunday
    ],
)
def test_is_reminder_day(day, expected):
    _FakeDate.today_value = day
    with patch.object(scheduled, "date", _FakeDate):
        assert scheduled._is_reminder_day() is expected


class _Case:
    def __init__(self, status):
        self.triage_at = datetime.utcnow() - timedelta(days=10)
        self.stable_at = datetime.utcnow() - timedelta(days=10)
        self.status = status


@pytest.mark.parametrize(
    "job, status, day, sends",
    [
        (scheduled.case_close_reminder, CaseStatus.triage, date(2025, 8, 18), True),
        (scheduled.case_close_reminder, CaseStatus.triage, date(2025, 8, 19), False),
        (scheduled.case_stable_reminder, CaseStatus.stable, date(2025, 8, 18), True),
        (scheduled.case_stable_reminder, CaseStatus.stable, date(2025, 8, 19), False),
    ],
)
def test_weekly_reminders_only_on_monday(job, status, day, sends):
    _FakeDate.today_value = day
    case = _Case(status)
    # unwrap the scheduler/timer decorators to call the job body for a single project
    fn = job
    while hasattr(fn, "__wrapped__"):
        fn = fn.__wrapped__

    with patch.object(scheduled, "date", _FakeDate), patch.object(
        scheduled, "get_all_by_status", return_value=[case]
    ), patch.object(scheduled, "send_case_close_reminder") as send:
        fn(db_session=None, project=type("P", (), {"id": 1})())

    assert send.called is sends

